 const [tab,setTab]=useState('discover'),[area,setArea]=useState('Bandra'),[query,setQuery]=useState(''),[budget,setBudget]=useState(500),[radius,setRadius]=useState(5),[samples,setSamples]=useState(process.env.NODE_ENV!=='production');
 const [coords,setCoords]=useState<{latitude:number;longitude:number}|null>(null),[results,setResults]=useState<Match[]>([]),[trace,setTrace]=useState<Trace[]>([]),[parser,setParser]=useState(''),[followUp,setFollowUp]=useState(''),[loading,setLoading]=useState(false),[searched,setSearched]=useState(false),[view,setView]=useState(immersive?'map':'list');
 const [user,setUser]=useState<User|null>(null),[auth,setAuth]=useState(false),[register,setRegister]=useState(false),[notice,setNotice]=useState(''),[error,setError]=useState(''),[active,setActive]=useState<{restaurant:Restaurant;menu:Dish[]}|null>(null),[showTrace,setShowTrace]=useState(false),[listening,setListening]=useState(false);
 const [offers,setOffers]=useState<Offer[]>([]),[history,setHistory]=useState<History[]>([]),[transactions,setTransactions]=useState<Transaction[]>([]),[favourites,setFavourites]=useState<Favourite[]>([]),[redemptions,setRedemptions]=useState<{id:number;discount_paise:number;created_at:string}[]>([]);
 const [owned,setOwned]=useState<Restaurant[]>([]),[selectedOwner,setSelectedOwner]=useState(0),[ownerMenu,setOwnerMenu]=useState<Dish[]>([]),[editDish,setEditDish]=useState<Dish|null>(null),[ownerAnalytics,setOwnerAnalytics]=useState<{restaurant_clicks:number;redemptions:number;discount_paise:number;campaigns:Offer[]}|null>(null);
