 const openRestaurant=useCallback((id:number,fromSearch=true,deal?:{id:number;amount:number})=>{setActiveDeal(deal||null);request<{restaurant:Restaurant;menu:Dish[]}>('/restaurants/'+id).then(setActive).catch(e=>setError(e.message));request('/restaurants/'+id+'/click',post({attribution:fromSearch?(attribution||undefined):undefined})).catch(()=>{});},[attribution]);
 async function action(task:()=>Promise<unknown>,success:string){setBusy(true);setError('');try{await task();setNotice(success)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 async function authenticate(e:FormEvent<HTMLFormElement>){
  e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget));
  await action(async()=>{const r=await request<{user:User}>(register?'/auth/register':'/auth/login',post(values));accountVersion.current++;setUser(r.user);setAuth(false);await refreshAccount()},'You’re signed in. Your next favourite is waiting.');
 }
 function locate(){
  if(!navigator.geolocation){setError('Location is unavailable. Choose a Mumbai area instead.');return}
  navigator.geolocation.getCurrentPosition(p=>{const {latitude,longitude}=p.coords;if(latitude<18.85||latitude>19.35||longitude<72.75||longitude>73.05){setError('BiteAI currently covers Mumbai only. Choose an area to explore.');return}setCoords({latitude,longitude});setNotice('Location updated. Search again for nearby matches.')},()=>setError('Location access was declined. You can still select a Mumbai area.'));
 }
